INSERT INTO "public"."bait_brands" ("id", "name", "specialty", "featured_products", "description", "image", "url", "source", "sort_order", "created_at", "updated_at") VALUES ('dsabaits', 'Dsabaits', 'Versatilidad y rendimiento', ARRAY['Boilies','Pastas','Pellets','Stick mix'], 'Dsabaits apuesta por cebos orientados al rendimiento, con mezclas atractivas y opciones versátiles para distintas épocas del año y diferentes masas de agua.', 'storage://team-assets/images/cebos/dsabaits.png', 'https://dsabaits.com/', 'seed', 4, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('kromquality', 'Kromquality', 'Calidad constante y cebos de confianza', ARRAY['Boilies','Pop Ups','Aditivos','Groundbait'], 'Kromquality transmite una línea de trabajo centrada en la consistencia del producto y en ofrecer soluciones fiables para sesiones rápidas o campañas largas.', 'storage://team-assets/images/cebos/kromquality.png', 'https://www.coletascarp.com/index.php/brand/krom-quality/', 'seed', 5, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('luxurybaits', 'Luxurybaits', 'Cebos premium y atracción intensa', ARRAY['Boilies premium','Dumbells','Liquids','Wafters'], 'Luxurybaits destaca por una propuesta cuidada, con cebos pensados para escenarios exigentes y pescadores que valoran tanto la calidad como la presentación.', 'storage://team-assets/images/cebos/luxurybaits.png', 'https://luxurybaits.com/', 'seed', 3, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('mainabaits', 'Maina Baits', 'Boilies artesanales y cebos naturales', ARRAY['Boilies','Pop Ups','Hookbaits','Liquids'], 'Maina Baits es una marca española centrada en el desarrollo de cebos artesanales para carpfishing, con una filosofía basada en ingredientes naturales y recetas probadas en escenarios reales.', 'storage://team-assets/images/cebos/mainabaits.png', 'https://mainabaits.com/', 'seed', 2, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('peralbaits', 'Peralbaits', 'Cebos adaptables para carpfishing', ARRAY['Boilies','Hookbaits','Remojos','Spod mix'], 'Peralbaits ofrece una selección enfocada en la pesca de carpa, con productos que combinan atractivo, practicidad y una propuesta adaptable a distintos estilos de pesca.', 'storage://team-assets/images/cebos/peralbaits.png', 'https://peralbaits.es/', 'seed', 7, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('proelitebaits', 'Proelitebaits', 'Boilies equilibrados y cebos técnicos', ARRAY['Boilies','Pop Ups','Hookbaits','Pellets'], 'Marca conocida en el mundo del carpfishing por ofrecer cebos bien trabajados, pensados para pescadores que buscan confianza y regularidad en sus sesiones.', 'storage://team-assets/images/cebos/proelitebaits.png', 'https://proelitebaits.com', 'seed', 1, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00'), ('superbaits', 'Superbaits', 'Atracción rápida y eficacia', ARRAY['Boilies rápidos','Pellets','Wafters','Boosters'], 'Superbaits es una opción interesante para quienes buscan cebos efectivos, directos y pensados para generar respuesta rápida sin renunciar a una buena base nutricional.', 'storage://team-assets/images/cebos/superbaits.png', 'https://www.santanacarp.com/fabricante/superbaits/', 'seed', 6, '2026-05-12 16:00:47.97018+00', '2026-05-12 16:00:47.97018+00');